import {newRepair} from './workshop-repair-model.mjs';
import {repairExamGrade,validRepairExam} from './workshop-repair-exam-model.mjs';
export function retryRepairCase(original,index){if(!validRepairExam(original)||!original.finished||original.retryOf||!Number.isInteger(index)||!original.cases[index]||repairExamGrade(original.cases[index]).score===100)return null;const e=structuredClone(original);e.id=crypto.randomUUID();e.retryOf=original.id;e.retryIndex=index;e.index=index;e.started=new Date().toISOString();e.finished=null;e.cases[index]={repair:newRepair(original.cases[index].repair),observations:[],submitted:false};return e;}
export const repairExamTotal=e=>e.retryOf?repairExamGrade(e.cases[e.retryIndex]).score:Math.round(e.cases.reduce((n,c)=>n+repairExamGrade(c).score,0)/4);
export function repairExamMastery(exams,retries=[]){const groups=new Map();for(const e of [...exams].sort((a,b)=>Date.parse(a.finished)-Date.parse(b.finished))){if(e.retryOf)continue;for(const c of e.cases){const key=c.repair.kind+':'+c.repair.fault;if(!groups.has(key))groups.set(key,{key,kind:c.repair.kind,fault:c.repair.fault,grades:[],retries:[]});groups.get(key).grades.push(repairExamGrade(c));}}for(const e of [...retries].sort((a,b)=>Date.parse(a.finished)-Date.parse(b.finished))){const c=e.cases[e.retryIndex],g=groups.get(c.repair.kind+':'+c.repair.fault);if(g)g.retries.push(repairExamGrade(c));}return [...groups.values()].map(g=>({...g,count:g.grades.length,first:g.grades[0].score,latest:g.grades.at(-1).score,status:g.grades.length<3?'early':g.grades.slice(-3).every(x=>x.verified&&x.score===100)?'consistent':'practice',remaining:g.grades.reduce((n,x)=>n+x.remaining.length,0),unnecessary:g.grades.reduce((n,x)=>n+x.unnecessary,0),missing:g.grades.filter(x=>!x.evidence).length}));}
